O(n) single pass.

```js
function productExceptSelf(nums) {
  const n = nums.length, res = new Array(n).fill(1);
  let l = 1; for (let i = 0; i < n; i++) { res[i] = l; l *= nums[i]; }
  let r = 1; for (let i = n - 1; i >= 0; i--) { res[i] *= r; r *= nums[i]; }
  return res;
}
```
Two passes, O(n) / O(1) extra.

```js
function maxSub(nums) {
  let cur = nums[0], best = nums[0];
  for (let i = 1; i < nums.length; i++) { cur = Math.max(nums[i], cur + nums[i]); best = Math.max(best, cur); }
  return best;
}
