```js
function rotate(A, K) {
  if (!A.length) return A;
  K = K % A.length;
  return A.slice(-K).concat(A.slice(0, -K));
}
```

Reverse trick: reverse all, then reverse first k, then reverse rest.
```js
function rotate(nums, k) {
  k %= nums.length;
  const rev = (l, r) => { while (l < r) [nums[l++], nums[r--]] = [nums[r], nums[l]]; };
  rev(0, nums.length - 1); rev(0, k - 1); rev(k, nums.length - 1);
}
```

Two pointers, O(n).
```js
function trap(h) {
  let l = 0, r = h.length - 1, lmax = 0, rmax = 0, res = 0;
  while (l < r) {
    if (h[l] < h[r]) { lmax = Math.max(lmax, h[l]); res += lmax - h[l++]; }
    else            { rmax = Math.max(rmax, h[r]); res += rmax - h[r--]; }
  }
  return res;
}
```

```js
function removeDuplicates(nums) {
  if (!nums.length) return 0;
  let w = 1;
  for (let r = 1; r < nums.length; r++) if (nums[r] !== nums[r-1]) nums[w++] = nums[r];
  return w;
}
```

Use first row/col as markers; separate flags for the first row/col themselves. O(1) extra.
```js
function setZeroes(m) {
  const R = m.length, C = m[0].length;
  let firstRow = false, firstCol = false;
  for (let c = 0; c < C; c++) if (m[0][c] === 0) firstRow = true;
  for (let r = 0; r < R; r++) if (m[r][0] === 0) firstCol = true;
  for (let r = 1; r < R; r++) for (let c = 1; c < C; c++) if (m[r][c] === 0) { m[r][0] = 0; m[0][c] = 0; }
  for (let r = 1; r < R; r++) for (let c = 1; c < C; c++) if (m[r][0] === 0 || m[0][c] === 0) m[r][c] = 0;
  if (firstRow) for (let c = 0; c < C; c++) m[0][c] = 0;
  if (firstCol) for (let r = 0; r < R; r++) m[r][0] = 0;
}
```

Transpose then reverse each row.
```js
function rotate(m) {
  const n = m.length;
  for (let i = 0; i < n; i++) for (let j = i + 1; j < n; j++) [m[i][j], m[j][i]] = [m[j][i], m[i][j]];
  for (const row of m) row.reverse();
}
```

```js
function spiral(m) {
  const res = [];
  let top = 0, bot = m.length - 1, l = 0, r = m[0].length - 1;
  while (top <= bot && l <= r) {
    for (let c = l; c <= r; c++) res.push(m[top][c]); top++;
    for (let rr = top; rr <= bot; rr++) res.push(m[rr][r]); r--;
    if (top <= bot) { for (let c = r; c >= l; c--) res.push(m[bot][c]); bot--; }
    if (l <= r) { for (let rr = bot; rr >= top; rr--) res.push(m[rr][l]); l++; }
  }
  return res;
}
```

Fill from the back.
```js
function merge(nums1, m, nums2, n) {
  let i = m - 1, j = n - 1, k = m + n - 1;
  while (j >= 0) nums1[k--] = i >= 0 && nums1[i] > nums2[j] ? nums1[i--] : nums2[j--];
}
