Mark visited by negation.
```js
function findDuplicates(nums) {
  const res = [];
  for (const n of nums) {
    const i = Math.abs(n) - 1;
    if (nums[i] < 0) res.push(i + 1);
    else nums[i] = -nums[i];
  }
  return res;
}
```

Track both min and max (negatives flip).
```js
function maxProduct(nums) {
  let mx = nums[0], mn = nums[0], best = nums[0];
  for (let i = 1; i < nums.length; i++) {
    const n = nums[i];
    if (n < 0) [mx, mn] = [mn, mx];
    mx = Math.max(n, mx * n);
    mn = Math.min(n, mn * n);
    best = Math.max(best, mx);
  }
  return best;
}
```

Two pointers from both ends toward middle.
```js
function sortedSquares(nums) {
  const res = new Array(nums.length);
  let l = 0, r = nums.length - 1, k = r;
  while (l <= r) {
    if (nums[l]**2 > nums[r]**2) { res[k--] = nums[l]**2; l++; }
    else { res[k--] = nums[r]**2; r--; }
  }
  return res;
}
```

```js
function isAnagram(s, t) {
  if (s.length !== t.length) return false;
  const c = {};
  for (const ch of s) c[ch] = (c[ch] || 0) + 1;
  for (const ch of t) if (--c[ch] < 0 || c[ch] === undefined) return false;
  return true;
}
```

```js
function groupAnagrams(strs) {
  const m = new Map();
  for (const s of strs) {
    const k = [...s].sort().join('');
    (m.get(k) || m.set(k, []).get(k)).push(s);
  }
  return [...m.values()];
}
```

```js
function firstUniqChar(s) {
  const c = {};
  for (const ch of s) c[ch] = (c[ch] || 0) + 1;
  for (let i = 0; i < s.length; i++) if (c[s[i]] === 1) return i;
  return -1;
}
```

```js
function longestConsecutive(nums) {
  const s = new Set(nums); let best = 0;
  for (const n of s) if (!s.has(n - 1)) {
    let cur = n, len = 1;
    while (s.has(cur + 1)) { cur++; len++; }
    best = Math.max(best, len);
  }
  return best;
}
```

```js
function subarraySum(nums, k) {
  const c = new Map([[0, 1]]);
  let sum = 0, count = 0;
  for (const n of nums) { sum += n; count += c.get(sum - k) || 0; c.set(sum, (c.get(sum) || 0) + 1); }
  return count;
}
```

```js
function isHappy(n) {
  const seen = new Set();
  const sq = x => [...String(x)].reduce((s, c) => s + (+c) ** 2, 0);
  while (n !== 1 && !seen.has(n)) { seen.add(n); n = sq(n); }
  return n === 1;
}
```

```js
function isIsomorphic(s, t) {
  const m1 = {}, m2 = {};
  for (let i = 0; i < s.length; i++) {
    if (m1[s[i]] !== undefined && m1[s[i]] !== t[i]) return false;
    if (m2[t[i]] !== undefined && m2[t[i]] !== s[i]) return false;
    m1[s[i]] = t[i]; m2[t[i]] = s[i];
  }
  return true;
}
```

```js
function wordPattern(pat, s) {
  const w = s.split(' ');
  if (w.length !== pat.length) return false;
  const p2w = {}, w2p = {};
  for (let i = 0; i < w.length; i++) {
    if ((p2w[pat[i]] || w[i]) !== w[i]) return false;
    if ((w2p[w[i]] || pat[i]) !== pat[i]) return false;
    p2w[pat[i]] = w[i]; w2p[w[i]] = pat[i];
  }
  return true;
}
```

```js
function isValidSudoku(b) {
  const seen = new Set();
  for (let r = 0; r < 9; r++) for (let c = 0; c < 9; c++) {
    const v = b[r][c]; if (v === '.') continue;
    const keys = [`r${r}${v}`, `c${c}${v}`, `b${(r/3|0)}${(c/3|0)}${v}`];
    for (const k of keys) { if (seen.has(k)) return false; seen.add(k); }
  }
  return true;
}
```

Bucket sort by frequency — O(n).
```js
function topK(nums, k) {
  const c = new Map();
  for (const n of nums) c.set(n, (c.get(n) || 0) + 1);
  const buckets = Array.from({ length: nums.length + 1 }, () => []);
  for (const [n, f] of c) buckets[f].push(n);
  const res = [];
  for (let i = buckets.length - 1; res.length < k; i--) res.push(...buckets[i]);
  return res.slice(0, k);
}
```

```js
function canConstruct(note, mag) {
  const c = {};
  for (const ch of mag) c[ch] = (c[ch] || 0) + 1;
  for (const ch of note) if (!c[ch]--) return false;
  return true;
}
```

```js
function containsNearbyDup(nums, k) {
  const seen = new Map();
  for (let i = 0; i < nums.length; i++) {
    if (seen.has(nums[i]) && i - seen.get(nums[i]) <= k) return true;
    seen.set(nums[i], i);
  }
  return false;
}
```

```js
function frequencySort(s) {
  const c = {};
  for (const ch of s) c[ch] = (c[ch] || 0) + 1;
  return Object.entries(c).sort((a, b) => b[1] - a[1]).map(([ch, n]) => ch.repeat(n)).join('');
}
```

Map balance→earliest-index. When balance repeats, subarray sums to 0.
```js
function findMaxLength(nums) {
  const first = new Map([[0, -1]]);
  let bal = 0, best = 0;
  for (let i = 0; i < nums.length; i++) {
    bal += nums[i] === 1 ? 1 : -1;
    if (first.has(bal)) best = Math.max(best, i - first.get(bal));
    else first.set(bal, i);
  }
  return best;
}
```

Sliding window with counter compare.
```js
function findAnagrams(s, p) {
  if (p.length > s.length) return [];
  const need = new Array(26).fill(0), have = new Array(26).fill(0);
  for (const c of p) need[c.charCodeAt(0) - 97]++;
  const res = [];
  for (let i = 0; i < s.length; i++) {
    have[s.charCodeAt(i) - 97]++;
    if (i >= p.length) have[s.charCodeAt(i - p.length) - 97]--;
    if (i >= p.length - 1 && need.every((n, k) => n === have[k])) res.push(i - p.length + 1);
  }
  return res;
}
```

```js
function isPalindrome(s) {
  let l = 0, r = s.length - 1;
  const ok = c => /[a-z0-9]/i.test(c);
  while (l < r) {
    while (l < r && !ok(s[l])) l++;
    while (l < r && !ok(s[r])) r--;
    if (s[l].toLowerCase() !== s[r].toLowerCase()) return false;
    l++; r--;
  }
  return true;
}
```

Expand around each center — O(n²).
```js
function longestPalindrome(s) {
  let start = 0, len = 0;
  const exp = (l, r) => { while (l >= 0 && r < s.length && s[l] === s[r]) { l--; r++; } return r - l - 1; };
  for (let i = 0; i < s.length; i++) {
    const a = exp(i, i), b = exp(i, i + 1), m = Math.max(a, b);
    if (m > len) { len = m; start = i - ((m - 1) >> 1); }
  }
  return s.slice(start, start + len);
}
```

