```js
function myAtoi(s) {
  const m = s.match(/^\s*([+-]?\d+)/);
  if (!m) return 0;
  const n = parseInt(m[1], 10);
  const MAX = 2**31 - 1, MIN = -(2**31);
  return Math.max(MIN, Math.min(MAX, n));
}
```

```js
function romanToInt(s) {
  const v = { I:1, V:5, X:10, L:50, C:100, D:500, M:1000 };
  let sum = 0;
  for (let i = 0; i < s.length; i++) {
    if (v[s[i]] < v[s[i+1]]) sum -= v[s[i]];
    else sum += v[s[i]];
  }
  return sum;
}
```

```js
function countAndSay(n) {
  let s = '1';
  for (let i = 1; i < n; i++) {
    let next = '', k = 0;
    while (k < s.length) {
      let j = k;
      while (j < s.length && s[j] === s[k]) j++;
      next += (j - k) + s[k];
      k = j;
    }
    s = next;
  }
  return s;
}
```

```js
function addBinary(a, b) {
  let i = a.length - 1, j = b.length - 1, carry = 0, res = '';
  while (i >= 0 || j >= 0 || carry) {
    const sum = (+(a[i--] || 0)) + (+(b[j--] || 0)) + carry;
    res = (sum % 2) + res;
    carry = sum > 1 ? 1 : 0;
  }
  return res;
}
```

```js
function multiply(a, b) {
  if (a === '0' || b === '0') return '0';
  const res = new Array(a.length + b.length).fill(0);
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--) {
      const p = +a[i] * +b[j] + res[i + j + 1];
      res[i + j + 1] = p % 10;
      res[i + j] += p / 10 | 0;
    }
  return res.join('').replace(/^0+/, '');
}
```

```js
function isValid(s) {
  const pair = { ')':'(', ']':'[', '}':'{' };
  const st = [];
  for (const c of s) {
    if ('([{'.includes(c)) st.push(c);
    else if (st.pop() !== pair[c]) return false;
  }
  return !st.length;
}
```

```js
function convert(s, r) {
  if (r === 1) return s;
  const rows = Array.from({ length: r }, () => '');
  let i = 0, dir = 1;
  for (const c of s) {
    rows[i] += c;
    if (i === 0) dir = 1;
    else if (i === r - 1) dir = -1;
    i += dir;
  }
  return rows.join('');
}
```

```js
class Trie {
  constructor() { this.root = {}; }
  insert(w) { let n = this.root; for (const c of w) n = n[c] ??= {}; n.$ = true; }
  search(w) { const n = this._find(w); return !!(n && n.$); }
  startsWith(p) { return !!this._find(p); }
  _find(w) { let n = this.root; for (const c of w) { if (!n[c]) return null; n = n[c]; } return n; }
}
```

```js
function isMatch(s, p) {
  const dp = Array.from({ length: s.length + 1 }, () => new Array(p.length + 1).fill(false));
  dp[0][0] = true;
  for (let j = 1; j <= p.length; j++) if (p[j-1] === '*') dp[0][j] = dp[0][j-2];
  for (let i = 1; i <= s.length; i++) for (let j = 1; j <= p.length; j++) {
    if (p[j-1] === '.' || p[j-1] === s[i-1]) dp[i][j] = dp[i-1][j-1];
    else if (p[j-1] === '*') dp[i][j] = dp[i][j-2] || ((p[j-2] === '.' || p[j-2] === s[i-1]) && dp[i-1][j]);
  }
  return dp[s.length][p.length];
}
```

```js
function threeSum(nums) {
  nums.sort((a, b) => a - b);
  const res = [];
  for (let i = 0; i < nums.length - 2; i++) {
    if (i && nums[i] === nums[i-1]) continue;
    let l = i + 1, r = nums.length - 1;
    while (l < r) {
      const s = nums[i] + nums[l] + nums[r];
      if (s === 0) {
        res.push([nums[i], nums[l], nums[r]]);
        while (l < r && nums[l] === nums[l+1]) l++;
        while (l < r && nums[r] === nums[r-1]) r--;
        l++; r--;
      } else s < 0 ? l++ : r--;
    }
  }
  return res;
}
```

```js
function maxArea(h) {
  let l = 0, r = h.length - 1, best = 0;
  while (l < r) {
    best = Math.max(best, (r - l) * Math.min(h[l], h[r]));
    if (h[l] < h[r]) l++; else r--;
  }
  return best;
}
```

```js
function sortColors(nums) {
  let l = 0, r = nums.length - 1, i = 0;
  while (i <= r) {
    if (nums[i] === 0) [nums[i], nums[l]] = [nums[l], nums[i]], i++, l++;
    else if (nums[i] === 2) [nums[i], nums[r]] = [nums[r], nums[i]], r--;
    else i++;
  }
}
```

```js
function validPalindrome(s) {
  const isP = (l, r) => { while (l < r) if (s[l++] !== s[r--]) return false; return true; };
  let l = 0, r = s.length - 1;
  while (l < r) {
    if (s[l] !== s[r]) return isP(l + 1, r) || isP(l, r - 1);
    l++; r--;
  }
  return true;
}
```

Iterate from the back, skip chars with pending backspaces.
```js
function backspaceCompare(s, t) {
  const nxt = (str, i) => { let bk = 0; while (i >= 0) { if (str[i] === '#') { bk++; i--; } else if (bk) { bk--; i--; } else break; } return i; };
  let i = s.length - 1, j = t.length - 1;
  while (i >= 0 || j >= 0) {
    i = nxt(s, i); j = nxt(t, j);
    if ((s[i] || '') !== (t[j] || '')) return false;
    i--; j--;
  }
  return true;
}
```

```js
function twoSum(nums, target) {
  let l = 0, r = nums.length - 1;
  while (l < r) {
    const s = nums[l] + nums[r];
    if (s === target) return [l + 1, r + 1];
    if (s < target) l++; else r--;
  }
}
```

```js
function numRescueBoats(people, limit) {
  people.sort((a, b) => a - b);
  let l = 0, r = people.length - 1, boats = 0;
  while (l <= r) {
    if (people[l] + people[r] <= limit) l++;
    r--; boats++;
  }
  return boats;
}
```

```js
function reverseOnlyLetters(s) {
  const a = [...s], isL = c => /[a-zA-Z]/.test(c);
  let l = 0, r = a.length - 1;
  while (l < r) {
    while (l < r && !isL(a[l])) l++;
    while (l < r && !isL(a[r])) r--;
    [a[l++], a[r--]] = [a[r], a[l]];
  }
  return a.join('');
}
```

