```js
function reverseVowels(s) {
  const a = [...s], v = 'aeiouAEIOU';
  let l = 0, r = a.length - 1;
  while (l < r) {
    while (l < r && !v.includes(a[l])) l++;
    while (l < r && !v.includes(a[r])) r--;
    [a[l++], a[r--]] = [a[r], a[l]];
