  let x = nums.length;
  for (let i = 0; i < nums.length; i++) x ^= i ^ nums[i];
  return x;
}
```

```js
function reverseBits(n) {
  let res = 0;
  for (let i = 0; i < 32; i++) { res = (res << 1) | (n & 1); n >>>= 1; }
  return res >>> 0;
}
```

