```js
function countBits(n) {
  const dp = new Array(n + 1).fill(0);
  for (let i = 1; i <= n; i++) dp[i] = dp[i >> 1] + (i & 1);
  return dp;
}
```

```js
function getSum(a, b) {
  while (b !== 0) {
    const carry = (a & b) << 1;
    a = a ^ b; b = carry;
  }
  return a;
}
```

```js
function binaryGap(N) {
  const b = N.toString(2);
  let max = 0, cur = -1;
  for (const ch of b) { if (ch === '1') { if (cur >= 0) max = Math.max(max, cur); cur = 0; } else if (cur >= 0) cur++; }
  return max;
}
```

```js
function binarySearch(nums, target) {
  let l = 0, r = nums.length - 1;
  while (l <= r) {
    const m = (l + r) >> 1;
    if (nums[m] === target) return m;
    if (nums[m] < target) l = m + 1; else r = m - 1;
  }
  return -1;
}
```

```js
function search(nums, target) {
  let l = 0, r = nums.length - 1;
  while (l <= r) {
    const m = (l + r) >> 1;
    if (nums[m] === target) return m;
    if (nums[l] <= nums[m]) {
      if (nums[l] <= target && target < nums[m]) r = m - 1; else l = m + 1;
    } else {
      if (nums[m] < target && target <= nums[r]) l = m + 1; else r = m - 1;
    }
  }
  return -1;
}
```

```js
function searchRange(nums, target) {
  const bs = (leftmost) => { let l = 0, r = nums.length; while (l < r) { const m = (l + r) >> 1; if (nums[m] > target || (leftmost && nums[m] === target)) r = m; else l = m + 1; } return l; };
  const lo = bs(true), hi = bs(false) - 1;
  return lo <= hi ? [lo, hi] : [-1, -1];
}
```

```js
function findPeak(nums) {
  let l = 0, r = nums.length - 1;
  while (l < r) {
    const m = (l + r) >> 1;
    if (nums[m] > nums[m + 1]) r = m; else l = m + 1;
  }
  return l;
}
```

```js
function searchInsert(nums, target) {
  let l = 0, r = nums.length;
  while (l < r) { const m = (l + r) >> 1; if (nums[m] < target) l = m + 1; else r = m; }
  return l;
}
```

```js
function mySqrt(x) {
  let l = 0, r = x, ans = 0;
  while (l <= r) {
    const m = (l + r) >> 1;
    if (m * m <= x) { ans = m; l = m + 1; } else r = m - 1;
  }
  return ans;
}
```

