function minEatingSpeed(piles, H) {
  const canFinish = k => piles.reduce((h, p) => h + Math.ceil(p / k), 0) <= H;
  let l = 1, r = Math.max(...piles);
  while (l < r) { const m = (l + r) >> 1; if (canFinish(m)) r = m; else l = m + 1; }
  return l;
}
```

```js
function findMedianSortedArrays(a, b) {
  if (a.length > b.length) [a, b] = [b, a];
  const m = a.length, n = b.length, half = (m + n + 1) >> 1;
  let l = 0, r = m;
  while (l <= r) {
    const i = (l + r) >> 1, j = half - i;
    const al = i === 0 ? -Infinity : a[i-1], ar = i === m ? Infinity : a[i];
    const bl = j === 0 ? -Infinity : b[j-1], br = j === n ? Infinity : b[j];
    if (al <= br && bl <= ar) {
      if ((m + n) % 2) return Math.max(al, bl);
      return (Math.max(al, bl) + Math.min(ar, br)) / 2;
    } else if (al > br) r = i - 1; else l = i + 1;
  }
}
```
